.table-wrapper {
  overflow-x: auto;

  table {
    border-collapse: collapse;
    table-layout: fixed;
    margin: 0.5rem 0 1rem 0;
    border: 1px solid rgba(var(--color-border-200));
    width: 100%;

    td,
    th {
      min-width: 1em;
      border: 1px solid rgba(var(--color-border-300));
      padding: 7px 10px;
      vertical-align: top;
      box-sizing: border-box;
      position: relative;
      transition: background-color 0.3s ease;

      > * {
        margin-bottom: 0;
      }

      &.selectedCell {
        user-select: none;

        &::after {
          position: absolute;
          content: "";
          top: -1px;
          left: -1px;
          height: calc(100% + 2px);
          width: calc(100% + 2px);
        }

        &.selectedCell-border-top::after {
          border-top: 2px solid rgba(var(--color-primary-100));
        }

        &.selectedCell-border-left::after {
          border-left: 2px solid rgba(var(--color-primary-100));
        }

        &.selectedCell-border-bottom::after {
          border-bottom: 2px solid rgba(var(--color-primary-100));
        }

        &.selectedCell-border-right::after {
          border-right: 2px solid rgba(var(--color-primary-100));
        }
      }
    }

    th {
      font-weight: 500;
      text-align: left;
    }

    tr[background="none"],
    tr:not([background]) {
      th {
        background-color: rgba(var(--color-background-90));
      }
    }
  }

  &.ProseMirror-selectednode {
    table {
      background-color: rgba(var(--color-primary-100), 0.2);
    }
  }
}

/* table dropdown */
.table-wrapper table .column-resize-handle {
  position: absolute;
  right: -1px;
  top: -1px;
  width: 2px;
  height: calc(100% + 2px);
  z-index: 5;
  background-color: rgba(var(--color-primary-100));
  pointer-events: none;
}

.table-wrapper .table-controls {
  position: absolute;

  .columns-control,
  .rows-control {
    transition: opacity ease-in 100ms;
    position: absolute;
    z-index: 5;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .columns-control {
    height: 20px;
    transform: translateY(-50%);

    .columns-control-div {
      color: white;
