  padding-bottom: var(--heading-1-padding-bottom);
  font-size: var(--font-size-h1);
  line-height: var(--line-height-h1);
  font-weight: 600;
}

.prose :where(h2.editor-heading-block):not(:where([class~="not-prose"], [class~="not-prose"] *)) {
